fn terrane_platform_tls_client(stream: &TerranePlatformCapability, server: String, deadline: terrane_int_support::Int, cancelled: bool) -> TerranePlatformResult { terrane_platform_support::tls_client(stream, &server, deadline.as_big().to_string().parse::<i128>().unwrap_or(-1), cancelled) }
fn terrane_platform_tls_read(stream: &TerranePlatformCapability, limit: terrane_int_support::Int, deadline: terrane_int_support::Int, cancelled: bool) -> TerranePlatformResult { terrane_platform_support::tls_read(stream, limit.as_big().to_string().parse::<i128>().unwrap_or(-1), deadline.as_big().to_string().parse::<i128>().unwrap_or(-1), cancelled) }
fn terrane_platform_tls_write(stream: &TerranePlatformCapability, data: Vec<u8>, deadline: terrane_int_support::Int, cancelled: bool) -> TerranePlatformResult { terrane_platform_support::tls_write(stream, &data, deadline.as_big().to_string().parse::<i128>().unwrap_or(-1), cancelled) }
